-- A Metodologia dos itens do Painel de Bordo (17/10/2026): a fórmula sobre os indicadores, com o formato, o percentual
-- e o espaço antes, no lugar do modelo de apuração fixo; cada item recebe a fórmula do modelo que tinha.
ALTER TABLE "painel_itens" ADD COLUMN "formula" TEXT NOT NULL DEFAULT '';
ALTER TABLE "painel_itens" ADD COLUMN "formato" TEXT NOT NULL DEFAULT 'MILHOES';
ALTER TABLE "painel_itens" ADD COLUMN "formato_acumulado" TEXT;
ALTER TABLE "painel_itens" ADD COLUMN "percentual" TEXT;
ALTER TABLE "painel_itens" ADD COLUMN "casas_percentual" INTEGER NOT NULL DEFAULT 1;
ALTER TABLE "painel_itens" ADD COLUMN "separar" BOOLEAN NOT NULL DEFAULT false;

UPDATE "painel_itens" SET "formula" = '[INDICADOR|Receita Líquida: Total]', "formato" = 'MILHOES', "formato_acumulado" = NULL, "percentual" = NULL, "casas_percentual" = 1, "separar" = false WHERE "modelo" = 'resultados.consolidado_rol';
UPDATE "painel_itens" SET "formula" = '[INDICADOR|Custo do Produto Vendido (CPV): Total]', "formato" = 'MILHOES', "formato_acumulado" = NULL, "percentual" = '[INDICADOR|Custo do Produto Vendido (CPV): Total] / [INDICADOR|Receita Líquida: Total]', "casas_percentual" = 1, "separar" = false WHERE "modelo" = 'resultados.consolidado_cpv';
