-- A assinatura na apuração passa a cobrir todos os Cadastros da Controladoria (um JSON, uma assinatura por cadastro).
ALTER TABLE "competencias" DROP COLUMN "painel_assinatura";
ALTER TABLE "competencias" ADD COLUMN "cadastros_assinatura" TEXT;
